import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || !validateSession(sessionToken)) {
            resp.sendError(403, "Unauthorized");
            return;
        }

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");

        // Input length check
        if (department != null && department.length() > 64) {
            resp.sendError(400, "Invalid department parameter");
            return;
        }

        // Basic character filter - blocks common attack chars
        if (department != null && department.matches(".*[;\\-\\-\\/\\*].*")) {
            log.warning("Suspicious chars in dept param: " + department);
            resp.sendError(400, "Invalid characters");
            return;
        }

        resp.setContentType("application/json");
        resp.setCharacterEncoding("UTF-8");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String query = buildQuery(reportType, dateRange, department);
            log.info("Executing report query for type=" + reportType);

            try (Statement stmt = conn.createStatement();
                 ResultSet rs = stmt.executeQuery(query)) {
                StringBuilder json = new StringBuilder("[\n");
                ResultSetMetaData meta = rs.getMetaData();
                int cols = meta.getColumnCount();
                boolean first = true;
                while (rs.next()) {
                    if (!first) json.append(",\n");
                    json.append("  {");
                    for (int i = 1; i <= cols; i++) {
                        if (i > 1) json.append(", ");
                        json.append("\"").append(meta.getColumnName(i))
                           .append("\": \"").append(rs.getString(i)).append("\"");
                    }
                    json.append("}");
                    first = false;
                }
                json.append("\n]");
                resp.getWriter().write(json.toString());
            }
        } catch (SQLException e) {
            log.severe("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String buildQuery(String reportType, String dateRange, String department) {
        String baseQuery;
        if ("summary".equals(reportType)) {
            baseQuery = "SELECT dept_name, COUNT(*) as cnt, SUM(amount) as total FROM transactions";
        } else {
            baseQuery = "SELECT id, dept_name, amount, tx_date, description FROM transactions";
        }

        StringBuilder where = new StringBuilder(" WHERE 1=1");
        if (dateRange != null) {
            switch (dateRange) {
                case "7d": where.append(" AND tx_date >= CURRENT_DATE - INTERVAL '7 days'"); break;
                case "30d": where.append(" AND tx_date >= CURRENT_DATE - INTERVAL '30 days'"); break;
                case "90d": where.append(" AND tx_date >= CURRENT_DATE - INTERVAL '90 days'"); break;
                default: where.append(" AND tx_date >= CURRENT_DATE - INTERVAL '30 days'"); break;
            }
        }

        if (department != null && !department.isEmpty()) {
            where.append(" AND dept_name = '" + department + "'");
        }

        if ("summary".equals(reportType)) {
            where.append(" GROUP BY dept_name ORDER BY total DESC");
        } else {
            where.append(" ORDER BY tx_date DESC LIMIT 500");
        }

        return baseQuery + where.toString();
    }

    private boolean validateSession(String token) {
        // Validates against session store
        return token != null && token.length() == 64 && token.matches("[a-f0-9]+");
    }
}
